1	//! Component detection: FC annotation, forwardRef, HOC-wrapped, ForwardRefExoticComponent.
2	
3	use std::collections::BTreeMap;
4	
5	use camino::Utf8Path;
6	use oxc_ast::ast::*;
7	
8	use crate::types::{CollectedTypeAlias, ComponentMapping, DetectionRule, DiagnosticCode};
9	
10	use super::evidence::{FunctionShape, Scope, renders};
11	use super::{ReactApi, SourceDataCollector, is_pascal_case};
12	
13	/// Peel any wrapping `as X` casts, `satisfies X` checks or `!` assertions down to the real
14	/// expression underneath. Needed because component libraries commonly cast a
15	/// forwardRef/HOC call to a hand-rolled wrapper type instead of relying on
16	/// `@types/react`'s own generics (Fluent UI's own source notes this is
17	/// "required due to lack of distributive union to support unions on
18	/// @types/react"); `satisfies` (TS 4.9+) is the modern equivalent of the same
19	/// pattern and must be peeled the same way.
20	pub(super) fn peel_expr<'a, 'b>(expr: &'b Expression<'a>) -> &'b Expression<'a> {
21	    let mut expr = expr;
22	    loop {
23	        expr = match expr {
24	            Expression::ParenthesizedExpression(parenthesized) => &parenthesized.expression,
25	            Expression::TSAsExpression(as_expr) => &as_expr.expression,
26	            Expression::TSSatisfiesExpression(sat_expr) => &sat_expr.expression,
27	            Expression::TSNonNullExpression(non_null) => &non_null.expression,
28	            _ => return expr,
29	        };
30	    }
31	}
32	
33	/// What a call wrapping an aliased component is, as read from the call before the component is known.
34	#[derive(Clone, Copy)]
35	pub(crate) struct AliasCall {
36	    /// The call follows the component-wrapper conventions (`memo`, `withX(...)`, `forwardRef`, ...).
37	    wrapper: bool,
38	    forward_ref: bool,
39	}
40	
41	/// An alias of a component that was not collected yet when the alias was read.
42	pub(crate) struct PendingAlias {
43	    name: String,
44	    inner: String,
45	    call: Option<AliasCall>,
46	    span: oxc_span::Span,
47	}
48	
49	enum AliasOutcome {
50	    Done,
51	    /// The aliased component is known but the call around it is not a component wrapper; the reason is the skip's message.
52	    Declined(String),
53	    NoBase,
54	}
55	
56	/// What the component rules read from a binding: its initializer, span and type annotation. Built from a
57	/// `const X = ...` declarator or from an `export default ...` expression, so both go through the same rules.
58	#[derive(Clone, Copy)]
59	pub(super) struct Binding<'b, 'a> {
60	    pub(super) init: Option<&'b Expression<'a>>,
61	    pub(super) span: oxc_span::Span,
62	    pub(super) annotation: Option<&'b TSTypeAnnotation<'a>>,
63	}
64	
65	impl<'b, 'a> Binding<'b, 'a> {
66	    pub(super) fn of(decl: &'b VariableDeclarator<'a>) -> Self {
67	        Self { init: decl.init.as_ref(), span: decl.span, annotation: decl.type_annotation.as_deref() }
68	    }
69	}
70	
71	/// Whether `bare` is a React export that types a function component: the shared family plus the forwardRef
72	/// component type. Used by `extract_props_from_type_annotation` (which additionally requires the props argument
73	/// itself to resolve) and `type_annotation_is_fc_family` below (which only needs to know the annotation *looked
74	/// like* one of these) so the two checks can't drift apart.
75	fn is_fc_family_type(bare: &str) -> bool {
76	    crate::react_types::FC_FAMILY_TYPE_NAMES.contains(&bare) || bare == "ForwardRefComponent"
77	}
78	
79	/// PascalCase a file's stem for naming an anonymous default-exported
80	/// component that has no identifier of its own — e.g. `button-group.tsx` →
81	/// `ButtonGroup`, `useButton.tsx` → `UseButton`. Splits on any non-alphanumeric
82	/// separator (`-`, `_`, `.`, space) and capitalizes each segment's first
83	/// character. Returns `None` when the path has no usable stem at all (e.g.
84	/// nothing but separators).
85	pub(super) fn pascal_case_from_file_stem(file_path: &Utf8Path) -> Option<String> {
86	    let stem = file_path.file_stem()?;
87	    let mut pascal = String::new();
88	    for segment in stem.split(|c: char| !c.is_alphanumeric()) {
89	        let mut chars = segment.chars();
90	        if let Some(first) = chars.next() {
91	            pascal.extend(first.to_uppercase());
92	            pascal.push_str(chars.as_str());
93	        }
94	    }
95	    (!pascal.is_empty()).then_some(pascal)
96	}
97	
98	impl<'src> SourceDataCollector<'src> {
99	    /// An asserted React component alias can replace the inner component's props before the alias is exported.
100	    pub(super) fn try_record_cast_component_alias<'a>(&mut self, decl: &VariableDeclarator<'a>, name: &str) {
101	        let Some(Expression::TSAsExpression(assertion)) = decl.init.as_ref() else { return };
102	        let Expression::Identifier(inner) = assertion.expression.without_parentheses() else { return };
103	        let has_base = self.data.component_mappings.iter().any(|mapping| mapping.is_binding_named(inner.name.as_str()));
104	        if !has_base {
105	            return;
106	        }
107	        let TSType::TSTypeReference(reference) = &assertion.type_annotation else { return };
108	        let type_name = self.extract_type_ref_name(reference);
109	        let Some(bare) = self.react_type_export(&type_name) else { return };
110	        if bare != "ForwardRefExoticComponent" && !is_fc_family_type(&bare) {
111	            return;
112	        }
113	        let Some(props) = reference.type_arguments.as_ref().and_then(|args| args.params.first()) else { return };
114	        let alias_name = format!("__{name}CastProps{}", decl.span.start);
115	        let alias_key = self.scoped_key(&alias_name);
116	        let target = self.ts_type_to_collected(props);
117	        self.data
118	            .type_aliases
119	            .insert(alias_key, CollectedTypeAlias::Passthrough { target, file_path: self.file_path.clone() });
120	        self.cast_component_aliases.insert(name.into(), (inner.name.as_str().to_owned(), alias_name.into()));
121	    }
122	
123	    // ─── Component detection helpers ──────────────────────────────────────────
124	
125	    /// Try to extract a PascalCase name from a VariableDeclarator's binding.
126	    pub(super) fn extract_pascal_name<'a>(&self, decl: &VariableDeclarator<'a>) -> Option<String> {
127	        match &decl.id {
128	            BindingPattern::BindingIdentifier(id) => {
129	                let name = id.name.as_str();
130	                if is_pascal_case(name) { Some(name.to_owned()) } else { None }
131	            }
132	            _ => None,
133	        }
134	    }
135	
136	    /// The ordered rules for a binding whose initializer may be a component; the first that matches wins.
137	    pub(super) fn detect_component<'a>(&mut self, binding: &Binding<'_, 'a>, name: &str) -> Option<ComponentMapping> {
138	        self.try_fc_annotation(binding, name)
139	            .or_else(|| self.try_forward_ref(binding, name))
140	            .or_else(|| self.try_hoc_wrapped(binding, name))
141	            .or_else(|| self.try_class_expression_wrapped(binding, name))
142	            .or_else(|| self.try_typed_function_expression(binding, name))
143	    }
144	
145	    /// Try to detect: `const Button: FC<ButtonProps> = ({ variant = 'primary' }) => ...`
146	    pub(super) fn try_fc_annotation<'a>(&mut self, decl: &Binding<'_, 'a>, name: &str) -> Option<ComponentMapping> {
147	        let type_ann = decl.annotation?;
148	        let init_params = match decl.init.as_ref() {
149	            Some(Expression::ArrowFunctionExpression(afe)) => Some(&*afe.params),
150	            Some(Expression::FunctionExpression(fe)) => Some(&*fe.params),
151	            _ => None,
152	        };
153	        self.extract_props_from_type_annotation(
154	            &type_ann.type_annotation,
155	            name,
156	            decl.span.start,
157	            decl.span.end,
158	            init_params,
159	        )
160	    }
161	
162	    pub(super) fn extract_props_from_type_annotation<'a>(
163	        &mut self,
164	        ty: &TSType<'a>,
165	        name: &str,
166	        span_start: u32,
167	        span_end: u32,
168	        init_params: Option<&FormalParameters<'a>>,
169	    ) -> Option<ComponentMapping> {
170	        match ty {
171	            TSType::TSTypeReference(tr) => {
172	                let type_name = self.extract_type_ref_name(tr);
173	                if !self.react_type_export(&type_name).is_some_and(|bare| is_fc_family_type(&bare)) {
174	                    return None;
175	                }
176	                let (props_name, type_args) = self.extract_props_arg(&tr.type_arguments)?;
177	                let (description, tags) = self.find_jsdoc_with_tags(span_start);
178	                Some(
179	                    ComponentMapping::new(
180	                        name.to_owned(),
181	                        props_name,
182	                        self.file_path.clone(),
183	                        span_start,
184	                        span_end,
185	                        DetectionRule::FcAnnotation,
186	                    )
187	                    .with_props_type_args(type_args)
188	                    .with_doc(description, tags)
189	                    .with_param_defaults(init_params.map(|p| self.extract_param_defaults(p)).unwrap_or_default()),
190	                )
191	            }
192	            TSType::TSParenthesizedType(p) => {
193	                self.extract_props_from_type_annotation(&p.type_annotation, name, span_start, span_end, init_params)
194	            }
195	            // `FC<DrawerProps> & { Panel: typeof Panel }`: the function-component member carries the props, the
196	            // other members are static properties attached to it.
197	            TSType::TSIntersectionType(members) => members.types.iter().find_map(|member| {
198	                self.extract_props_from_type_annotation(member, name, span_start, span_end, init_params)
199	            }),
200	            _ => None,
201	        }
202	    }
203	
204	    /// Try to detect: `const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(...)`
205	    pub(super) fn try_forward_ref<'a>(&mut self, decl: &Binding<'_, 'a>, name: &str) -> Option<ComponentMapping> {
206	        let init = decl.init.as_ref()?;
207	        let call = match peel_expr(init) {
208	            Expression::CallExpression(ce) => ce,
209	            _ => return None,
210	        };
211	        if !self.is_forward_ref_call(call) {
212	            return None;
213	        }
214	
215	        // forwardRef<RefType, PropsType>(fn) — PropsType is the second type parameter
216	        let type_params = call.type_arguments.as_ref()?;
217	        if type_params.params.len() < 2 {
218	            return None;
219	        }
220	        let props_type = &type_params.params[1];
221	        let (props_name, type_args) = self.extract_type_name_from_type(props_type)?;
222	
223	        // The render function is forwardRef's call argument — its first parameter is
224	        // props (the second is `ref`, which never carries destructured defaults we care about).
225	        let render_params = match call.arguments.first() {
226	            Some(Argument::FunctionExpression(fe)) => Some(&fe.params),
227	            Some(Argument::ArrowFunctionExpression(afe)) => Some(&afe.params),
228	            _ => None,
229	        };
230	        let param_defaults = render_params.map(|p| self.extract_param_defaults(p)).unwrap_or_default();
231	        let (description, tags) = self.find_jsdoc_with_tags(decl.span.start);
232	
233	        Some(
234	            ComponentMapping::new(
235	                name.to_owned(),
236	                props_name,
237	                self.file_path.clone(),
238	                decl.span.start,
239	                decl.span.end,
240	                DetectionRule::ForwardRef,
241	            )
242	            .with_props_type_args(type_args)
243	            .with_doc(description, tags)
244	            .with_param_defaults(param_defaults),
245	        )
246	    }
