248	    /// Try to detect: `const Button = ({ variant }: ButtonProps) => ...` and the `function` expression form. The
249	    /// function must show it renders (see `evidence`): a typed first parameter alone also describes helpers such as
250	    /// `FormatName = (u: User) => string`. A first parameter that is not a named type is not a props object.
251	    pub(super) fn try_typed_function_expression<'a>(
252	        &mut self,
253	        decl: &Binding<'_, 'a>,
254	        name: &str,
255	    ) -> Option<ComponentMapping> {
256	        let (params, shape) = match peel_expr(decl.init.as_ref()?) {
257	            Expression::ArrowFunctionExpression(afe) => (&*afe.params, FunctionShape::of_arrow(afe)),
258	            Expression::FunctionExpression(fe) => (&*fe.params, FunctionShape::of_function(fe)),
259	            _ => return None,
260	        };
261	        let type_ann = params.items.first()?.type_annotation.as_ref()?;
262	        if let Err(reason) = renders(&shape, &*self) {
263	            self.decline_reason = Some(format!("'{name}' takes a typed props parameter but {reason}"));
264	            return None;
265	        }
266	        let (props_name, type_args) = self.extract_type_name_from_type(&type_ann.type_annotation)?;
267	        let param_defaults = self.extract_param_defaults(params);
268	        let (description, tags) = self.find_jsdoc_with_tags(decl.span.start);
269	        Some(
270	            ComponentMapping::new(
271	                name.to_owned(),
272	                props_name,
273	                self.file_path.clone(),
274	                decl.span.start,
275	                decl.span.end,
276	                DetectionRule::TypedFunctionExpression,
277	            )
278	            .with_props_type_args(type_args)
279	            .with_doc(description, tags)
280	            .with_param_defaults(param_defaults),
281	        )
282	    }
