284	    /// Try to detect: `const Button = anyHOC(function Button(props: ButtonProps) {...})`
285	    pub(super) fn try_hoc_wrapped<'a>(&mut self, decl: &Binding<'_, 'a>, name: &str) -> Option<ComponentMapping> {
286	        let init = decl.init.as_ref()?;
287	        let call = match peel_expr(init) {
288	            Expression::CallExpression(ce) => ce,
289	            _ => return None,
290	        };
291	
292	        // First arg should be a function with a typed props param — or a forwardRef() call.
293	        let first_arg = call.arguments.first()?;
294	
295	        // `memo(forwardRef(…))`: the props come from forwardRef's type arguments, or from its render function.
296	        if let Argument::CallExpression(inner) = first_arg {
297	            if !self.is_forward_ref_call(inner) {
298	                return None;
299	            }
300	            // `forwardRef<Ref, Props>(…)` names the props in its second type argument; otherwise the render function's
301	            // first parameter does. A call with one type argument and no function (`forwardRef<Ref>()`) names neither.
302	            let props_type = inner.type_arguments.as_ref().and_then(|type_params| type_params.params.get(1));
303	            let Some(props_type) = props_type else {
304	                let render = inner.arguments.first()?;
305	                return self.mapping_from_typed_function(decl, name, call, render, DetectionRule::ForwardRef);
306	            };
307	            let (props_name, type_args) = self.extract_type_name_from_type(props_type)?;
308	            let (description, tags) = self.find_jsdoc_with_tags(decl.span.start);
309	            return Some(
310	                ComponentMapping::new(
311	                    name.to_owned(),
312	                    props_name,
313	                    self.file_path.clone(),
314	                    decl.span.start,
315	                    decl.span.end,
316	                    DetectionRule::ForwardRef,
317	                )
318	                .with_props_type_args(type_args)
319	                .with_doc(description, tags),
320	            );
321	        }
322	        let rule = if self.is_forward_ref_call(call) { DetectionRule::ForwardRef } else { DetectionRule::HocWrapper };
323	        self.mapping_from_typed_function(decl, name, call, first_arg, rule)
324	    }
