326	    /// The component a wrapper call builds from a render function whose first parameter names the props type:
327	    /// `memo(function Button(props: ButtonProps) {…})`, and the same inside `memo(forwardRef(…))`. `call` is the outermost
328	    /// wrapper call, whose type arguments may add props (`wrapper.rs`).
329	    fn mapping_from_typed_function<'a>(
330	        &mut self,
331	        decl: &Binding<'_, 'a>,
332	        name: &str,
333	        call: &CallExpression<'a>,
334	        function: &Argument<'a>,
335	        rule: DetectionRule,
336	    ) -> Option<ComponentMapping> {
337	        let (fn_name, params, shape) = match function {
338	            Argument::FunctionExpression(fe) => {
339	                (fe.id.as_ref().map(|id| id.name.as_str()), &fe.params, FunctionShape::of_function(fe))
340	            }
341	            Argument::ArrowFunctionExpression(afe) => (None, &afe.params, FunctionShape::of_arrow(afe)),
342	            _ => return None,
343	        };
344	
345	        // Rules out anonymous utility functions, which aren't components.
346	        if let Some(fn_name_str) = fn_name
347	            && !is_pascal_case(fn_name_str)
348	        {
349	            return None;
350	        }
351	
352	        let first_param = params.items.first()?;
353	        let type_ann = first_param.type_annotation.as_ref()?;
354	        // `debounce((q: Row) => …)` and `createSelector((s: State) => …)` have the same shape as `memo(…)`.
355	        if let Err(reason) = renders(&shape, &*self) {
356	            self.decline_reason = Some(format!("'{name}' wraps a typed function that {reason}"));
357	            return None;
358	        }
359	        let (props_name, type_args) = self.extract_type_name_from_type(&type_ann.type_annotation)?;
360	
361	        let param_defaults = self.extract_param_defaults(params);
362	        let (description, tags) = self.find_jsdoc_with_tags(decl.span.start);
363	
364	        let mapping = ComponentMapping::new(
365	            name.to_owned(),
366	            props_name,
367	            self.file_path.clone(),
368	            decl.span.start,
369	            decl.span.end,
370	            rule,
371	        )
372	        .with_props_type_args(type_args)
373	        .with_doc(description, tags)
374	        .with_param_defaults(param_defaults);
375	        // `factory<Payload>((props: P) => …)`: a generic wrapper's result type can add props, as in `wrapper.rs`.
376	        Some(match self.wrapper_callee(call) {
377	            Some(callee) => mapping.with_wrapper_callee(callee),
378	            None => mapping,
379	        })
380	    }
381	
382	    /// Try to detect declared `ForwardRefExoticComponent<Props>` and `MemoExoticComponent<(props: Props) => JSX>` values.
383	    ///
384	    /// Common in .d.ts files — no initializer, just a type annotation.
385	    pub(super) fn try_exotic_component_decl<'a>(
386	        &mut self,
387	        decl: &VariableDeclarator<'a>,
388	        name: &str,
389	    ) -> Option<ComponentMapping> {
390	        let type_ann = decl.type_annotation.as_ref()?;
391	        let ct = self.ts_type_to_collected(&type_ann.type_annotation);
392	
393	        let is_react_type = |name: &str, expected: &str| {
394	            name == expected
395	                || name.rsplit_once('.').is_some_and(|(prefix, suffix)| {
396	                    suffix == expected
397	                        && (prefix == "React"
398	                            || self.data.imports.iter().any(|binding| {
399	                                binding.local_name == prefix
400	                                    && binding.exported_name == "*"
401	                                    && super::is_react_module(&binding.specifier)
402	                            }))
403	                })
404	        };
405	        let exotic_args = |ty: &crate::types::CollectedType| match ty {
406	            crate::types::CollectedType::Named { name, args } if is_react_type(name, "ForwardRefExoticComponent") => {
407	                Some((args.clone(), false))
408	            }
409	            crate::types::CollectedType::Named { name, args } if is_react_type(name, "MemoExoticComponent") => {
410	                Some((args.clone(), true))
411	            }
412	            _ => None,
413	        };
414	        let (args, memoized) = match &ct {
415	            crate::types::CollectedType::Intersection(members) => members.iter().find_map(exotic_args),
416	            other => exotic_args(other),
417	        }?;
418	
419	        let first_arg = args.first()?;
420	
421	        // RefAttributes is metadata on the value, not a prop base. Keep every other member: declaration generators
422	        // often write several props objects into one ForwardRefExoticComponent argument.
423	        let props_type = match first_arg {
424	            crate::types::CollectedType::Function { params, .. } if memoized => params.first()?.clone(),
425	            _ if memoized => return None,
426	            crate::types::CollectedType::Intersection(members) => {
427	                let mut props: Vec<_> = members
428	                    .iter()
429	                    .filter(|member| {
430	                        !matches!(member, crate::types::CollectedType::Named { name, .. }
431	                            if is_react_type(name, "RefAttributes"))
432	                    })
433	                    .cloned()
434	                    .collect();
435	                match props.len() {
436	                    0 => return None,
437	                    1 => props.remove(0),
438	                    _ => crate::types::CollectedType::Intersection(props),
439	                }
440	            }
441	            other => other.clone(),
442	        };
443	
444	        let (props_name, props_args) = match props_type {
445	            crate::types::CollectedType::Named { name, args } => (name, args),
446	            props => {
447	                let name = crate::types::synthesized_alias_name(self.data.type_aliases.len());
448	                let key = self.scoped_key(&name);
449	                self.data.type_aliases.insert(
450	                    key,
451	                    crate::types::CollectedTypeAlias::Passthrough { target: props, file_path: self.file_path.clone() },
452	                );
453	                (name.into(), vec![])
454	            }
455	        };
456	
457	        Some(
458	            ComponentMapping::new(
459	                name.to_owned(),
460	                props_name,
461	                self.file_path.clone(),
462	                decl.span.start,
463	                decl.span.end,
464	                if memoized { DetectionRule::MemoExoticDecl } else { DetectionRule::ForwardRefExoticDecl },
465	            )
466	            .with_props_type_args(props_args)
467	            .with_doc(self.find_jsdoc(decl.span.start), BTreeMap::new())
468	            .with_param_defaults(rustc_hash::FxHashMap::default()),
469	        )
470	    }
