472	    /// A dependency can publish a component as `declare const Tab: (props: TabProps) => ReactElement | null`.
473	    pub(super) fn try_declared_callable_component<'a>(
474	        &mut self,
475	        decl: &VariableDeclarator<'a>,
476	        name: &str,
477	    ) -> Option<ComponentMapping> {
478	        let annotation = &decl.type_annotation.as_ref()?.type_annotation;
479	        let (params, return_type, type_parameters) = if let TSType::TSFunctionType(function) = annotation {
480	            (function.params.as_ref(), function.return_type.as_ref(), function.type_parameters.as_deref())
481	        } else if let TSType::TSTypeLiteral(literal) = annotation {
482	            let mut calls = literal.members.iter().filter_map(|member| match member {
483	                TSSignature::TSCallSignatureDeclaration(call) => Some(call.as_ref()),
484	                TSSignature::TSIndexSignature(_)
485	                | TSSignature::TSPropertySignature(_)
486	                | TSSignature::TSConstructSignatureDeclaration(_)
487	                | TSSignature::TSMethodSignature(_) => None,
488	            });
489	            let call = calls.next()?;
490	            if calls.next().is_some() {
491	                return None;
492	            }
493	            (call.params.as_ref(), call.return_type.as_deref()?, call.type_parameters.as_deref())
494	        } else {
495	            return None;
496	        };
497	        let [parameter] = params.items.as_slice() else { return None };
498	        let return_type = self.ts_type_to_collected(&return_type.type_annotation);
499	        let is_element = |name: &str| {
500	            matches!(name, "React.ReactElement" | "React.JSX.Element" | "JSX.Element")
501	                || name.strip_suffix(".JSX.Element").is_some_and(|namespace| {
502	                    self.data.imports.iter().any(|binding| {
503	                        binding.local_name == namespace
504	                            && binding.exported_name == "*"
505	                            && matches!(binding.specifier.as_str(), "react/jsx-runtime" | "react/jsx-dev-runtime")
506	                    })
507	                })
508	                || self.data.imports.iter().any(|binding| {
509	                    binding.local_name == name
510	                        && binding.exported_name == "ReactElement"
511	                        && super::is_react_module(&binding.specifier)
512	                })
513	        };
514	        let returns_element = |ty: &crate::types::CollectedType| match ty {
515	            crate::types::CollectedType::Named { name, .. } => is_element(name),
516	            crate::types::CollectedType::Union(members) => members.iter().any(|member| {
517	                if let crate::types::CollectedType::Named { name, .. } = member { is_element(name) } else { false }
518	            }),
519	            _ => false,
520	        };
521	        if !returns_element(&return_type) {
522	            return None;
523	        }
524	        let (props_name, mut props_args) =
525	            self.extract_type_name_from_type(&parameter.type_annotation.as_ref()?.type_annotation)?;
526	        let type_params: Vec<crate::types::TypeName> = type_parameters
527	            .map(|declaration| declaration.params.iter().map(|param| param.name.name.as_str().into()).collect())
528	            .unwrap_or_default();
529	        if crate::types::is_synthesized_alias(&props_name) && !type_params.is_empty() {
530	            self.data.type_alias_params.insert(self.scoped_key(&props_name), type_params.clone());
531	            props_args = type_params
532	                .iter()
533	                .map(|name| crate::types::CollectedType::Named { name: name.clone(), args: Vec::new() })
534	                .collect();
535	        }
536	        let mut mapping = ComponentMapping::new(
537	            name.to_owned(),
538	            props_name,
539	            self.file_path.clone(),
540	            decl.span.start,
541	            decl.span.end,
542	            DetectionRule::FunctionDeclaration,
543	        )
544	        .with_props_type_args(props_args)
545	        .with_doc(self.find_jsdoc(decl.span.start), BTreeMap::new());
546	        mapping.type_params = type_params;
547	        Some(mapping)
548	    }
