550	    /// Try to detect: `export default function(props: Props) { ... }` — an
551	    /// anonymous default-exported function component, common in Next.js page
552	    /// files. There's no identifier to name it after, so the PascalCased
553	    /// file stem is used instead. Mirrors Pattern 4's
554	    /// (`visit_function`'s named-function handling) exact contract: a
555	    /// missing type annotation is a flagged skip, but zero declared params
556	    /// at all is silent — same as the named-function sibling.
557	    pub(super) fn try_anonymous_default_export_component<'a>(&mut self, func: &Function<'a>) {
558	        let Some(name) = pascal_case_from_file_stem(&self.file_path) else { return };
559	
560	        let Some(first_param) = func.params.items.first() else { return };
561	        let Some(type_ann) = &first_param.type_annotation else {
562	            self.record_skip(
563	                DiagnosticCode::SkippedCandidate,
564	                format!("'{name}' is an anonymous default-exported function component with an untyped first param"),
565	                first_param.span,
566	            );
567	            return;
568	        };
569	        let Some((props_name, type_args)) = self.extract_type_name_from_type(&type_ann.type_annotation) else {
570	            self.record_skip(
571	                DiagnosticCode::SkippedCandidate,
572	                format!(
573	                    "'{name}' is an anonymous default-exported function component whose first param's type \
574	                     annotation isn't a recognizable props type reference"
575	                ),
576	                type_ann.span,
577	            );
578	            return;
579	        };
580	
581	        let (description, tags) = self.find_jsdoc_with_tags(func.span.start);
582	        let param_defaults = self.extract_param_defaults(&func.params);
583	        self.anonymous_default = Some(func.span.start);
584	        self.data.component_mappings.push(
585	            ComponentMapping::new(
586	                name,
587	                props_name,
588	                self.file_path.clone(),
589	                func.span.start,
590	                func.span.end,
591	                DetectionRule::AnonymousDefaultExport,
592	            )
593	            .without_binding()
594	            .with_props_type_args(type_args)
595	            .with_doc(description, tags)
596	            .with_param_defaults(param_defaults),
597	        );
598	    }
