600	    /// True when `class`'s `extends` clause is `Component`/`PureComponent`
601	    /// (bare or `React.`-qualified). Returns the matched bare name for use in
602	    /// diagnostic messages.
603	    pub(super) fn super_class_is_component_family<'a>(&self, class: &Class<'a>) -> Option<&'static str> {
604	        let super_name = self.expression_to_ident_name(&class.heritage.as_ref()?.expression);
605	        match self.react_type_export(&super_name)?.as_str() {
606	            "Component" => Some("Component"),
607	            "PureComponent" => Some("PureComponent"),
608	            _ => None,
609	        }
