612	    /// Try to detect: `class Button extends React.Component<Props> { ... }`
613	    /// (or bare `Component`/`PureComponent`). Shared by both a named
614	    /// `ClassDeclaration` (called directly from `visit_class`) and an
615	    /// anonymous `ClassExpression` assigned to a variable (via
616	    /// `try_class_expression_wrapped` below). Silent on every failure path,
617	    /// mirroring `try_fc_annotation`/`try_forward_ref`/`try_hoc_wrapped`'s own
618	    /// contract — callers decide whether and how to surface a diagnostic.
619	    pub(super) fn try_class_component<'a>(&mut self, class: &Class<'a>, name: &str) -> Option<ComponentMapping> {
620	        self.super_class_is_component_family(class)?;
621	        let type_args = class.heritage.as_ref()?.type_arguments.as_ref()?;
622	        let props_type = type_args.params.first()?;
623	        let (props_name, props_type_args) = self.extract_type_name_from_type(props_type)?;
624	        let (description, tags) = self.find_jsdoc_with_tags(class.span.start);
625	        Some(
626	            ComponentMapping::new(
627	                name.to_owned(),
628	                props_name,
629	                self.file_path.clone(),
630	                class.span.start,
631	                class.span.end,
632	                DetectionRule::ClassComponent,
633	            )
634	            .with_props_type_args(props_type_args)
635	            .with_doc(description, tags)
636	            .with_param_defaults(rustc_hash::FxHashMap::default()),
637	        )
638	    }
