640	    /// Try to detect: `const Button = class extends React.Component<Props> { ... }`
641	    /// — an anonymous class expression assigned to a PascalCase binding. Only
642	    /// fires when the class expression has no name of its own; a self-named
643	    /// one (`class Button extends ...`) is instead picked up directly by
644	    /// `visit_class` under its own identifier, avoiding a duplicate mapping
645	    /// under both names.
646	    pub(super) fn try_class_expression_wrapped<'a>(
647	        &mut self,
648	        decl: &Binding<'_, 'a>,
649	        name: &str,
650	    ) -> Option<ComponentMapping> {
651	        let init = decl.init.as_ref()?;
652	        let Expression::ClassExpression(class) = init else { return None };
653	        if class.id.is_some() {
654	            return None;
655	        }
656	        self.try_class_component(class, name)
657	    }
