659	    /// True when `decl`'s type annotation (after peeling parens) is a bare
660	    /// reference to one of the FC-family type names, regardless of whether
661	    /// its props type argument is itself extractable.
662	    ///
663	    /// Used by the no-initializer Pattern 5 diagnostic guard in `visit.rs`:
664	    /// `try_fc_annotation` already runs unconditionally for every PascalCase
665	    /// declarator (init or no init) and would have produced a mapping had the
666	    /// props argument resolved, so reaching this check with no mapping means
667	    /// the props argument specifically was the unrecognized part — an exotic
668	    /// `TSType` shape `extract_type_name_from_type` doesn't match — not that
669	    /// the declaration isn't FC-shaped at all.
670	    pub(super) fn type_annotation_is_fc_family<'a>(&self, decl: &VariableDeclarator<'a>) -> bool {
671	        fn peel_parens<'t, 'a>(ty: &'t TSType<'a>) -> &'t TSType<'a> {
672	            match ty {
673	                TSType::TSParenthesizedType(p) => peel_parens(&p.type_annotation),
674	                other => other,
675	            }
676	        }
677	        let Some(type_ann) = decl.type_annotation.as_ref() else { return false };
678	        let TSType::TSTypeReference(tr) = peel_parens(&type_ann.type_annotation) else { return false };
679	        let type_name = self.extract_type_ref_name(tr);
680	        self.react_type_export(&type_name).is_some_and(|bare| is_fc_family_type(&bare))
681	    }
