683	    /// Rename an already-collected component mapping to its real public export name
684	    /// when the mapping's own identifier is immediately wrapped by an *unrecognized*
685	    /// call and reassigned to a new binding — e.g. Headless UI's real
686	    /// `export let ListboxButton = forwardRefWithAs(ButtonFn) as X`. `forwardRefWithAs`
687	    /// is a library-defined wrapper, not `React.forwardRef` itself, so `try_forward_ref`
688	    /// never matches it; meanwhile `ButtonFn` — a standalone top-level function
689	    /// declaration — was already independently collected as its own component by the
690	    /// `visit_function` Pattern 4 check, under the wrong (inner, implementation-only)
691	    /// name. Without this, the real export name never appears at all.
692	    ///
693	    /// Also handles the same rename with no wrapper call at all — a bare passthrough
694	    /// alias, `const Button = InternalCompoundedButton;` (optionally `as X`), antd's
695	    /// real `Button` export shape.
696	    ///
697	    /// Clones the matched mapping under the new name rather than renaming it in
698	    /// place: a second, different alias to the same base
699	    /// (`const A = Base; const Bcopy = Base;`) is a genuinely distinct exported
700	    /// binding, not the same rename twice, and renaming in place would make the
701	    /// base unfindable for that second alias — silently dropping it. The base's
702	    /// own (implementation-only) name is filtered out of the final output in
703	    /// `finish()` via `aliased_away`.
704	    pub(super) fn try_rename_identifier_wrapped_component<'a>(&mut self, decl: &Binding<'_, 'a>, name: &str) -> bool {
705	        let Some((inner, call)) = self.alias_shape(decl) else { return false };
706	        match self.alias_outcome(name, &inner, call) {
707	            AliasOutcome::Done => true,
708	            AliasOutcome::Declined(reason) => {
709	                self.decline_reason = Some(reason);
710	                false
711	            }
712	            AliasOutcome::NoBase => {
713	                self.alias_candidate = Some((inner, call));
714	                false
715	            }
716	        }
717	    }
718	
719	    /// The component `decl` re-binds, `const Button = Inner` or `memo(Inner)`, and what the call is, read before `Inner`
720	    /// needs to be known. `None` when the initializer is not that shape, or the call names the props it builds with.
721	    fn alias_shape<'a>(&mut self, decl: &Binding<'_, 'a>) -> Option<(String, Option<AliasCall>)> {
722	        let init = decl.init.as_ref()?;
723	        let (inner, call) = match peel_expr(init) {
724	            Expression::CallExpression(call) => match aliased_component(call) {
725	                Some(Expression::Identifier(id)) => (id.name.as_str().to_owned(), Some(&**call)),
726	                _ => return None,
727	            },
728	            Expression::Identifier(id) => (id.name.as_str().to_owned(), None),
729	            _ => return None,
730	        };
731	        let Some(call) = call else { return Some((inner, None)) };
732	        // The component it receives is not the one it builds when a type argument names the props.
733	        if self.call_names_props_type(call) {
734	            return None;
735	        }
736	        // `getDisplayName(Card)` has the same shape as `memo(Card)` but returns a string; only a call that follows the
737	        // component-wrapper conventions produces a component.
738	        // `Object.assign(Impl, { Item })` returns `Impl` itself with the statics attached.
739	        let wrapper = is_component_alias_call(&*self, call);
740	        // `forwardRef(Inner)` makes a component that takes a `ref` even when `Inner` is a plain typed function.
741	        Some((inner, Some(AliasCall { wrapper, forward_ref: self.is_forward_ref_call(call) })))
742	    }
743	
744	    /// Bind `name` to a clone of the component `inner` once that is collected.
745	    fn alias_outcome(&mut self, name: &str, inner: &str, call: Option<AliasCall>) -> AliasOutcome {
746	        let Some(base) = self.data.component_mappings.iter().find(|m| m.is_binding_named(inner)) else {
747	            return AliasOutcome::NoBase;
748	        };
749	        if call.is_some_and(|call| !call.wrapper) {
750	            return AliasOutcome::Declined(format!(
751	                "'{name}' passes component '{inner}' to a call that does not look like a component wrapper"
752	            ));
753	        }
754	        let mut alias = base.clone();
755	        if call.is_some_and(|call| call.forward_ref) {
756	            alias.rule = DetectionRule::ForwardRef;
757	        }
758	        alias.component_name = name.to_owned();
759	        self.data.component_mappings.push(alias);
760	        self.aliased_away.insert(inner.into());
761	        AliasOutcome::Done
762	    }
763	
764	    /// Hold back `const Button = Inner` whose `Inner` is not collected yet: it may be declared further down the file.
765	    /// Only the alias shape `try_rename_identifier_wrapped_component` just read, and only after every other rule
766	    /// declined it.
767	    pub(super) fn try_defer_identifier_alias(&mut self, name: &str, span: oxc_span::Span) -> bool {
768	        let Some((inner, call)) = self.alias_candidate.take() else { return false };
769	        self.pending_aliases.push(PendingAlias { name: name.to_owned(), inner, call, span });
770	        true
771	    }
772	
773	    /// Resolve the held aliases now that every declaration in the file is known; an alias of an alias takes more than
774	    /// one pass. What is still unresolved is reported as the skip it would have been.
775	    pub(super) fn promote_identifier_aliases(&mut self) {
776	        let mut pending = std::mem::take(&mut self.pending_aliases);
777	        loop {
778	            let before = pending.len();
779	            let mut waiting = Vec::new();
780	            for alias in pending {
781	                if self.data.component_mappings.iter().any(|m| m.is_binding_named(&alias.name)) {
782	                    continue;
783	                }
784	                match self.alias_outcome(&alias.name, &alias.inner, alias.call) {
785	                    AliasOutcome::Done => {}
786	                    AliasOutcome::Declined(reason) => {
787	                        self.record_skip(DiagnosticCode::SkippedCandidate, reason, alias.span);
788	                    }
789	                    AliasOutcome::NoBase => waiting.push(alias),
790	                }
791	            }
792	            pending = waiting;
793	            if pending.is_empty() || pending.len() == before {
794	                break;
795	            }
796	        }
797	        let reported: Vec<PendingAlias> = pending
798	            .into_iter()
799	            .filter(|alias| {
800	                !super::is_constant_name(&alias.name)
801	                    && !self.pending_factory_calls.iter().any(|factory| factory.name == alias.name)
802	            })
803	            .collect();
804	        for alias in reported {
805	            self.record_skip(
806	                DiagnosticCode::SkippedCandidate,
807	                format!(
808	                    "'{}' is a PascalCase binding but matched no known component pattern \
809	                     (FC annotation, forwardRef, HOC wrapper, or identifier alias)",
810	                    alias.name
811	                ),
812	                alias.span,
813	            );
814	        }
815	    }
816	
817	    /// Record `const X = Imported.Member` and `const X = Imported` as a component whose props are the imported
818	    /// component's (`ComponentProps<typeof Imported.Member>`), when `Imported` is an import binding and the component is
819	    /// PascalCase.
820	    pub(super) fn try_record_imported_member_alias<'a>(&mut self, decl: &Binding<'_, 'a>, name: &str) -> bool {
821	        let Some(init) = decl.init.as_ref() else { return false };
822	        let target = match peel_expr(init) {
823	            Expression::StaticMemberExpression(member) => {
824	                let Expression::Identifier(object) = &member.object else { return false };
825	                let property = member.property.name.as_str();
826	                if !self.imported_names.contains(object.name.as_str()) || !is_pascal_case(property) {
827	                    return false;
828	                }
829	                format!("{}.{property}", object.name)
830	            }
831	            // A constant is not a component whatever it is bound to; `const ORIGIN = Thing` says nothing about `Thing`.
832	            Expression::Identifier(id)
833	                if self.imported_names.contains(id.name.as_str())
834	                    && is_pascal_case(id.name.as_str())
835	                    && !super::is_constant_name(name) =>
836	            {
837	                id.name.to_string()
838	            }
839	            _ => return false,
840	        };
841	        self.push_imported_alias(name, target, decl.span);
842	        true
843	    }
844	
845	    /// Record `const { Option } = Imported` and `const { Option: Opt } = Imported` as components named by the binding,
846	    /// one per PascalCase member, when `Imported` is an import binding.
847	    pub(super) fn try_record_destructured_imports<'a>(&mut self, declarator: &VariableDeclarator<'a>) {
848	        let BindingPattern::ObjectPattern(pattern) = &declarator.id else { return };
849	        let Some(Expression::Identifier(object)) = declarator.init.as_ref().map(peel_expr) else { return };
850	        if !self.imported_names.contains(object.name.as_str()) {
851	            return;
852	        }
853	        for property in &pattern.properties {
854	            let PropertyKey::StaticIdentifier(key) = &property.key else { continue };
855	            let BindingPattern::BindingIdentifier(local) = &property.value else { continue };
856	            let (key, local) = (key.name.as_str(), local.name.as_str());
857	            if !is_pascal_case(key) || !is_pascal_case(local) || super::is_constant_name(local) {
858	                continue;
859	            }
860	            self.push_imported_alias(local, format!("{}.{key}", object.name), declarator.span);
861	        }
862	    }
863	
864	    fn push_imported_alias(&mut self, name: &str, target: String, span: oxc_span::Span) {
865	        let (description, tags) = self.find_jsdoc_with_tags(span.start);
866	        self.data.component_mappings.push(
867	            ComponentMapping::new(
868	                name.to_owned(),
869	                "ComponentProps".into(),
870	                self.file_path.clone(),
871	                span.start,
872	                span.end,
873	                DetectionRule::ImportedMemberAlias,
874	            )
875	            .with_props_type_args(vec![crate::types::CollectedType::TypeOf(target.into())])
876	            .with_doc(description, tags),
877	        );
878	    }
879	
880	    /// Whether `call` makes a component that takes a `ref` whatever its props type declares: React's `forwardRef` however
881	    /// it is imported or spelled, or another module's own `forwardRef` (React Aria's).
882	    fn is_forward_ref_call(&self, call: &CallExpression<'_>) -> bool {
883	        if self.react_api(&call.callee) == Some(ReactApi::ForwardRef) {
884	            return true;
885	        }
886	        let name = match peel_expr(&call.callee) {
887	            Expression::Identifier(id) => id.name.as_str(),
888	            Expression::StaticMemberExpression(member) => member.property.name.as_str(),
889	            _ => return false,
890	        };
891	        name == "forwardRef" && self.react_api(&call.callee).is_none()
892	    }
893	
894	    /// Extract the callee name of a call expression (simple ident or member expr).
895	    pub(super) fn extract_callee_name<'a>(&self, call: &CallExpression<'a>) -> Option<String> {
896	        match &call.callee {
897	            Expression::Identifier(id) => Some(id.name.as_str().to_owned()),
898	            Expression::StaticMemberExpression(me) => {
899	                Some(format!("{}.{}", self.expression_to_ident_name(&me.object), me.property.name.as_str()))
900	            }
901	            _ => None,
902	        }
903	    }
904	}
905	
906	/// Whether a call wrapping a component returns a component: React's `memo` and `forwardRef` as the file binds them,
907	/// or the ecosystem's conventions.
908	pub(super) fn is_component_wrapper(scope: &dyn Scope, call: &CallExpression<'_>) -> bool {
909	    scope.is_react_wrapper(call) || is_component_wrapper_call(call)
910	}
911	
912	/// Whether a call returns the component it is given, so that what it is bound or exported as is that component: a
913	/// component wrapper, or `Object.assign(Impl, { Item })`, which returns `Impl` with the statics attached. The one place
914	/// that says which calls make an alias of a component; [`aliased_component`] says which argument it is.
915	pub(super) fn is_component_alias_call(scope: &dyn Scope, call: &CallExpression<'_>) -> bool {
916	    is_component_wrapper(scope, call) || is_object_assign_call(call)
917	}
918	
919	/// The argument of a component alias call that is the component: the first.
920	pub(super) fn aliased_component<'a, 'b>(call: &'b CallExpression<'a>) -> Option<&'b Expression<'a>> {
921	    call.arguments.first()?.as_expression().map(peel_expr)
922	}
923	
924	/// Whether the call is `Object.assign(...)`.
925	pub(super) fn is_object_assign_call(call: &CallExpression<'_>) -> bool {
926	    matches!(&call.callee, Expression::StaticMemberExpression(callee)
927	        if callee.property.name == "assign"
928	            && matches!(&callee.object, Expression::Identifier(object) if object.name == "Object"))
929	}
930	
931	/// Whether a call wrapping a component returns a component, by the ecosystem's conventions:
932	/// `memo`, anything named like `forwardRef`, `withX(...)` higher-order components, `createXComponent(...)` factories,
933	/// `observer`, and curried wrappers such as `connect(...)(Component)` or `styled(...)(Component)`.
934	fn is_component_wrapper_call(call: &CallExpression<'_>) -> bool {
935	    // `(forwardRef as forwardRefType)(X)` is React Aria's spelling of `forwardRef(X)`.
936	    let callee = match peel_expr(&call.callee) {
937	        Expression::Identifier(id) => id.name.as_str(),
938	        Expression::StaticMemberExpression(m) => m.property.name.as_str(),
939	        Expression::CallExpression(_) => return true,
940	        _ => return false,
941	    };
942	    let lower = callee.to_ascii_lowercase();
943	    callee == "memo"
944	        || callee == "observer"
945	        || lower.contains("forwardref")
946	        || callee.contains("Component")
947	        || (callee.len() > 4 && callee.starts_with("with") && callee[4..].starts_with(|c: char| c.is_ascii_uppercase()))
948	}
