1	//! Evidence that a function renders, so a typed PascalCase function is a component and not a helper that happens to
2	//! take an object. A typed first parameter alone admits `FormatName = (u: User) => string`, `debounce((q: Row) => …)`
3	//! and selectors, so every rule that infers a component from a function asks this first.
4	//!
5	//! What the function returns decides, not what appears anywhere in its body: JSX built in a nested callback or never
6	//! returned is not evidence.
7	
8	use oxc_ast::ast::*;
9	use oxc_ast_visit::{Visit, walk};
10	use oxc_syntax::scope::ScopeFlags;
11	use rustc_hash::FxHashSet;
12	
13	/// Why a function was judged not to render. Carried into the skip diagnostic.
14	pub(super) type NoRender = &'static str;
15	
16	/// Names whose type, as a return annotation, means the function renders.
17	const ELEMENT_TYPE_NAMES: &[&str] = &["Element", "ReactElement", "ReactNode", "ReactPortal", "JSX"];
18	
19	/// Callees that produce an element, by name. Preact's `h` is not here: so short a name proves nothing until it is
20	/// known to be imported from Preact (`Scope::is_preact_h`).
21	const ELEMENT_FACTORIES: &[&str] = &["createElement", "cloneElement", "jsx", "jsxs", "jsxDEV", "createPortal"];
22	
23	/// Whether a callee name names an element factory, given the receiver it was called on (`Preact` in `Preact.h(…)`).
24	/// `h` counts only as Preact's own binding, bare or on Preact's namespace: `codec.h(…)` and a local helper called `h`
25	/// are not factories.
26	pub(super) fn is_element_factory_name(name: &str, receiver: Option<&str>, scope: &dyn Scope) -> bool {
27	    if name == "h" {
28	        return scope.is_preact_h(receiver);
29	    }
30	    ELEMENT_FACTORIES.contains(&name)
31	}
32	
33	/// Whether a call's callee is an element factory: see [`is_element_factory_name`].
34	pub(super) fn is_element_factory_callee(callee: &Expression<'_>, scope: &dyn Scope) -> bool {
35	    match callee {
36	        Expression::Identifier(id) => is_element_factory_name(id.name.as_str(), None, scope),
37	        Expression::StaticMemberExpression(m) => {
38	            let receiver = match &m.object {
39	                Expression::Identifier(object) => Some(object.name.as_str()),
40	                _ => Some(""),
41	            };
42	            is_element_factory_name(m.property.name.as_str(), receiver, scope)
43	        }
44	        _ => false,
45	    }
46	}
47	
48	/// Whether a type name, as written in this file, can be React's or the global `JSX` namespace's. Given the name's
49	/// leftmost segment (`React` for `React.ReactNode`), so an element-like name imported from another module does not
50	/// count.
51	pub(super) type ReactBinding<'f> = &'f dyn Scope;
52	
53	/// What the file around a function says about the names it uses.
54	pub(super) trait Scope {
55	    /// Whether a type name can be React's: see [`ReactBinding`].
56	    fn may_be_react(&self, name: &str) -> bool;
57	    /// Whether a call to this name returns an element: a same-file function declared to return one.
58	    fn is_element_helper(&self, name: &str) -> bool;
59	    /// Whether the call is React's `memo(…)` or `forwardRef(…)`, by where its callee was imported from.
60	    fn is_react_wrapper(&self, call: &CallExpression<'_>) -> bool;
61	    /// Whether `h` called bare (`receiver` is `None`) or on `receiver` (`Preact.h`) is Preact's, by where it was
62	    /// imported from.
63	    fn is_preact_h(&self, receiver: Option<&str>) -> bool;
64	}
65	
66	fn leftmost_and_rightmost<'n>(name: &'n TSTypeName<'_>) -> Option<(&'n str, &'n str)> {
67	    match name {
68	        TSTypeName::IdentifierReference(id) => Some((id.name.as_str(), id.name.as_str())),
69	        TSTypeName::QualifiedName(q) => {
70	            let mut left = &q.left;
71	            while let TSTypeName::QualifiedName(inner) = left {
72	                left = &inner.left;
73	            }
74	            match left {
75	                TSTypeName::IdentifierReference(id) => Some((id.name.as_str(), q.right.name.as_str())),
76	                _ => None,
77	            }
78	        }
79	        _ => None,
80	    }
81	}
82	
83	/// Whether a return type annotation names a renderable result bound to React: `JSX.Element`, `ReactNode`,
84	/// `ReactElement`, a union containing one, or `Promise` of one (async server components).
85	pub(super) fn type_renders(ty: &TSType<'_>, react: ReactBinding<'_>) -> bool {
86	    match ty {
87	        TSType::TSTypeReference(r) => {
88	            let Some((left, right)) = leftmost_and_rightmost(&r.type_name) else { return false };
89	            if right == "Promise" {
90	                return r
91	                    .type_arguments
92	                    .as_ref()
93	                    .and_then(|a| a.params.first())
94	                    .is_some_and(|t| type_renders(t, react));
95	            }
96	            ELEMENT_TYPE_NAMES.contains(&right) && react.may_be_react(left)
97	        }
98	        TSType::TSUnionType(u) => u.types.iter().any(|t| type_renders(t, react)),
99	        TSType::TSParenthesizedType(p) => type_renders(&p.type_annotation, react),
100	        _ => false,
101	    }
102	}
103	
104	fn callee_name<'n>(callee: &'n Expression<'_>) -> Option<&'n str> {
105	    match callee {
106	        Expression::Identifier(id) => Some(id.name.as_str()),
107	        Expression::StaticMemberExpression(m) => Some(m.property.name.as_str()),
108	        _ => None,
109	    }
110	}
111	
112	fn is_hook_name(name: &str) -> bool {
113	    name.strip_prefix("use").is_some_and(|rest| rest.starts_with(|c: char| c.is_ascii_uppercase()))
114	}
115	
116	fn is_children(expr: &Expression<'_>) -> bool {
117	    match expr {
118	        Expression::Identifier(id) => id.name == "children",
119	        Expression::StaticMemberExpression(m) => m.property.name == "children",
120	        _ => false,
121	    }
122	}
123	
124	/// Finds JSX or an element factory call that can be part of an expression's value: through conditionals, logical
125	/// operators, arrays and call arguments (`items.map(i => <li/>)`, `createPortal(<div/>, el)`), but not inside an object
126	/// literal, whose JSX is a property's value rather than the expression's.
127	struct ElementInValue<'s> {
128	    found: bool,
129	    scope: &'s dyn Scope,
130	}
131	
132	impl<'a> Visit<'a> for ElementInValue<'_> {
133	    fn visit_jsx_element(&mut self, _it: &JSXElement<'a>) {
134	        self.found = true;
135	    }
136	
137	    fn visit_jsx_fragment(&mut self, _it: &JSXFragment<'a>) {
138	        self.found = true;
139	    }
140	
141	    fn visit_call_expression(&mut self, it: &CallExpression<'a>) {
142	        let name = callee_name(&it.callee);
143	        let calls_helper = matches!(&it.callee, Expression::Identifier(id) if self.scope.is_element_helper(&id.name));
144	        if calls_helper || is_element_factory_callee(&it.callee, self.scope) {
145	            self.found = true;
146	        // These calls preserve the JSX value; an arbitrary call may turn it into a Response or other data.
147	        } else if name.is_some_and(|name| matches!(name, "map" | "flatMap" | "reduce"))
148	            || matches!(&it.callee, Expression::StaticMemberExpression(member)
149	                if matches!(&member.object, Expression::Identifier(id) if id.name == "Promise")
150	                    && matches!(member.property.name.as_str(), "resolve" | "all"))
151	        {
152	            walk::walk_call_expression(self, it);
153	        }
154	    }
155	
156	    // JSX passed to a constructor, such as `new ImageResponse(<div />)`, is not the function's return value.
157	    fn visit_new_expression(&mut self, _it: &NewExpression<'a>) {}
158	
159	    fn visit_object_expression(&mut self, _it: &ObjectExpression<'a>) {}
160	}
161	
162	fn value_has_element(expr: &Expression<'_>, scope: &dyn Scope) -> bool {
163	    let mut finder = ElementInValue { found: false, scope };
164	    finder.visit_expression(expr);
165	    finder.found
166	}
167	
168	/// What one returned value says about the function.
169	fn returns_element(expr: &Expression<'_>, element_locals: &FxHashSet<String>, scope: &dyn Scope) -> bool {
170	    match expr.without_parentheses() {
171	        // Rendering nothing is a valid render.
172	        Expression::NullLiteral(_) => true,
173	        Expression::Identifier(id) if element_locals.contains(id.name.as_str()) => true,
174	        // A component invoked directly: `return JoinList({ ... })`.
175	        Expression::CallExpression(call) if callee_name(&call.callee).is_some_and(super::is_pascal_case) => true,
176	        e if is_children(e) => true,
177	        e => value_has_element(e, scope),
178	    }
179	}
180	
181	/// Walks one function's own body, not nested functions: its `return`s, its top-level hook calls, and the local
182	/// variables it initializes with an element (`const content = <div/>; return content`).
183	/// A local is declared before the `return` that uses it, so each `return` is judged as it is reached.
184	struct OwnBody<'s> {
185	    returns_element: bool,
186	    element_locals: FxHashSet<String>,
187	    calls_hook: bool,
188	    nested: u32,
189	    scope: &'s dyn Scope,
190	}
191	
192	impl<'s> OwnBody<'s> {
193	    fn new(scope: &'s dyn Scope) -> Self {
194	        Self { returns_element: false, element_locals: FxHashSet::default(), calls_hook: false, nested: 0, scope }
195	    }
196	}
197	
198	impl<'a> Visit<'a> for OwnBody<'_> {
199	    fn visit_return_statement(&mut self, it: &ReturnStatement<'a>) {
200	        if self.nested == 0
201	            && it.argument.as_ref().is_some_and(|r| returns_element(r, &self.element_locals, self.scope))
202	        {
203	            self.returns_element = true;
204	        }
205	        walk::walk_return_statement(self, it);
206	    }
207	
208	    fn visit_variable_declarator(&mut self, it: &VariableDeclarator<'a>) {
209	        if self.nested == 0
210	            && let (BindingPattern::BindingIdentifier(id), Some(init)) = (&it.id, &it.init)
211	            && value_has_element(init, self.scope)
212	        {
213	            self.element_locals.insert(id.name.to_string());
214	        }
215	        walk::walk_variable_declarator(self, it);
216	    }
217	
218	    fn visit_call_expression(&mut self, it: &CallExpression<'a>) {
219	        if self.nested == 0 && callee_name(&it.callee).is_some_and(is_hook_name) {
220	            self.calls_hook = true;
221	        }
222	        walk::walk_call_expression(self, it);
223	    }
224	
225	    fn visit_function(&mut self, it: &Function<'a>, flags: ScopeFlags) {
226	        self.nested += 1;
227	        walk::walk_function(self, it, flags);
228	        self.nested -= 1;
229	    }
230	
231	    fn visit_arrow_function_expression(&mut self, it: &ArrowFunctionExpression<'a>) {
232	        self.nested += 1;
233	        walk::walk_arrow_function_expression(self, it);
234	        self.nested -= 1;
235	    }
236	}
237	
238	/// A function body: a block, or an arrow's single expression or block.
239	pub(super) enum Body<'b, 'a> {
240	    Block(&'b FunctionBody<'a>),
241	    /// An arrow's body, and whether it is a single expression (`=> <div/>`) rather than a block.
242	    Arrow(&'b ArrowFunctionBody<'a>, bool),
243	}
244	
245	/// The parts of a function that decide whether it renders.
246	pub(super) struct FunctionShape<'b, 'a> {
247	    pub generator: bool,
248	    pub return_type: Option<&'b TSTypeAnnotation<'a>>,
249	    pub body: Option<Body<'b, 'a>>,
250	}
251	
252	impl<'b, 'a> FunctionShape<'b, 'a> {
253	    pub(super) fn of_arrow(f: &'b ArrowFunctionExpression<'a>) -> Self {
254	        Self {
255	            generator: false,
256	            return_type: f.return_type.as_deref(),
257	            body: Some(Body::Arrow(&f.body, f.is_expression())),
258	        }
259	    }
260	
261	    pub(super) fn of_function(f: &'b Function<'a>) -> Self {
262	        Self { generator: f.generator, return_type: f.return_type.as_deref(), body: f.body.as_deref().map(Body::Block) }
263	    }
264	}
265	
266	/// `Ok` when the function renders; `Err` with the reason it does not.
267	pub(super) fn renders(shape: &FunctionShape<'_, '_>, react: ReactBinding<'_>) -> Result<(), NoRender> {
268	    if shape.generator {
269	        return Err("is a generator");
270	    }
271	    if let Some(annotation) = shape.return_type {
272	        return if type_renders(&annotation.type_annotation, react) {
273	            Ok(())
274	        } else {
275	            Err("declares a return type that is not React's element type")
276	        };
277	    }
278	    let renders = match &shape.body {
279	        None => return Err("has no body and no element return type"),
280	        Some(Body::Arrow(body, true)) => {
281	            body.as_expression().is_some_and(|expr| returns_element(expr, &FxHashSet::default(), react))
282	        }
283	        Some(Body::Arrow(body, false)) => {
284	            let mut own = OwnBody::new(react);
285	            own.visit_arrow_function_body(body);
286	            own.calls_hook || own.returns_element
287	        }
288	        Some(Body::Block(body)) => {
289	            let mut own = OwnBody::new(react);
290	            own.visit_function_body(body);
291	            own.calls_hook || own.returns_element
292	        }
293	    };
294	    if renders {
295	        Ok(())
296	    } else {
297	        Err("never returns an element: no returned JSX, element, null, children or component call, and no hook call")
298	    }
299	}
300	
301	/// Names of module-level functions whose declared return type is an element, which makes a call to them element
302	/// evidence: `renderByProp(render, props, <button />)` with `renderByProp(...): React.ReactElement`. Judged on the
303	/// declaration alone, so a helper that returns something else without saying so is not counted.
304	pub(super) fn element_helpers(program: &Program<'_>) -> FxHashSet<String> {
305	    let mut foreign = FxHashSet::default();
306	    for stmt in &program.body {
307	        if let Statement::ImportDeclaration(import) = stmt
308	            && !super::is_react_module(&super::js_text::lossy(import.source.value))
309	        {
310	            for spec in import.specifiers.iter().flatten() {
311	                foreign.insert(spec.local().name.to_string());
312	            }
313	        }
314	    }
315	    let react = Foreign(&foreign);
316	    let declarations: Vec<&Declaration<'_>> = program.body.iter().filter_map(|stmt| stmt.as_declaration()).collect();
317	
318	    // `type Output = React.ReactElement` and aliases of aliases.
319	    let mut aliases = FxHashSet::default();
320	    loop {
321	        let before = aliases.len();
322	        for declaration in &declarations {
323	            if let Declaration::TSTypeAliasDeclaration(alias) = declaration
324	                && names_element(&alias.type_annotation, &react, &aliases)
325	            {
326	                aliases.insert(alias.id.name.to_string());
327	            }
328	        }
329	        if aliases.len() == before {
330	            break;
331	        }
332	    }
333	
334	    let returns_element = |annotation: Option<&TSTypeAnnotation<'_>>| {
335	        annotation.is_some_and(|a| names_element(&a.type_annotation, &react, &aliases))
336	    };
337	    let mut helpers = FxHashSet::default();
338	    for declaration in declarations {
339	        match declaration {
340	            Declaration::FunctionDeclaration(f) => {
341	                if let Some(id) = f.id.as_ref().filter(|_| returns_element(f.return_type.as_deref())) {
342	                    helpers.insert(id.name.to_string());
343	                }
344	            }
345	            Declaration::VariableDeclaration(vars) => {
346	                for declarator in &vars.declarations {
347	                    let (BindingPattern::BindingIdentifier(id), Some(init)) = (&declarator.id, &declarator.init) else {
348	                        continue;
349	                    };
350	                    let annotation = match init.without_parentheses() {
351	                        Expression::ArrowFunctionExpression(f) => f.return_type.as_deref(),
352	                        Expression::FunctionExpression(f) => f.return_type.as_deref(),
353	                        _ => None,
354	                    };
355	                    if returns_element(annotation) {
356	                        helpers.insert(id.name.to_string());
357	                    }
358	                }
359	            }
360	            _ => {}
361	        }
362	    }
363	    helpers
364	}
365	
366	/// The imports that are not React's, seen before the file is walked.
367	struct Foreign<'f>(&'f FxHashSet<String>);
368	
369	impl Scope for Foreign<'_> {
370	    fn may_be_react(&self, name: &str) -> bool {
371	        !self.0.contains(name)
372	    }
373	
374	    fn is_preact_h(&self, _receiver: Option<&str>) -> bool {
375	        false
376	    }
377	
378	    fn is_element_helper(&self, _name: &str) -> bool {
379	        false
380	    }
381	
382	    fn is_react_wrapper(&self, _call: &CallExpression<'_>) -> bool {
383	        false
384	    }
385	}
386	
387	/// Whether a type is an element type or a local alias of one. A `Promise` of one is not: the call returns the promise.
388	fn names_element(ty: &TSType<'_>, react: ReactBinding<'_>, aliases: &FxHashSet<String>) -> bool {
389	    match ty {
390	        TSType::TSTypeReference(r) => match &r.type_name {
391	            TSTypeName::IdentifierReference(id) if aliases.contains(id.name.as_str()) => true,
392	            name => {
393	                leftmost_and_rightmost(name).is_some_and(|(_, right)| right != "Promise") && type_renders(ty, react)
394	            }
395	        },
396	        TSType::TSUnionType(u) => u.types.iter().any(|t| names_element(t, react, aliases)),
397	        TSType::TSParenthesizedType(p) => names_element(&p.type_annotation, react, aliases),
398	        _ => false,
399	    }
400	}
