174	    /// Record `const Center = chakra("div", { ... })` as a candidate: a call given an intrinsic tag name and a config
175	    /// object, whose props type is the one declared in this file for that tag (`interface CenterProps extends
176	    /// HTMLChakraProps<"div">`). Nothing here names a library; calls that build elements rather than components
177	    /// (`createElement("div", { ... })`) are excluded by name, as React's own API.
178	    pub(super) fn try_record_tagged_factory<'a>(
179	        &mut self,
180	        decl: &super::component::Binding<'_, 'a>,
181	        name: &str,
182	    ) -> bool {
183	        let Some(init) = decl.init else { return false };
184	        let Expression::CallExpression(call) = super::component::peel_expr(init) else { return false };
185	        if call.type_arguments.is_some() {
186	            return false;
187	        }
188	        let [tag, config] = call.arguments.as_slice() else { return false };
189	        let Some(Expression::StringLiteral(tag)) = tag.as_expression().map(super::component::peel_expr) else {
190	            return false;
191	        };
192	        let tag_name = tag.value.as_str().map(str::to_owned);
193	        let is_tag = tag.value.as_str().is_some_and(|name| {
194	            name.starts_with(|c: char| c.is_ascii_lowercase())
195	                && name.chars().all(|c| c.is_ascii_alphanumeric() || c == '-')
196	        });
197	        let has_config =
198	            matches!(config.as_expression().map(super::component::peel_expr), Some(Expression::ObjectExpression(_)));
199	        let Some(callee) = self.extract_callee_name(call) else { return false };
200	        let element_builder = match callee.rsplit_once('.') {
201	            Some((receiver, name)) => super::evidence::is_element_factory_name(name, Some(receiver), &*self),
202	            None => super::evidence::is_element_factory_name(&callee, None, &*self),
203	        };
204	        if !is_tag || !has_config || element_builder {
