209	            name: name.to_owned(),
210	            needs_payload: false,
211	            tag: tag_name,
212	            type_args: Vec::new(),
213	            callee: None,
214	            rule: DetectionRule::TaggedFactory,
215	            description,
216	            tags,
217	            span: decl.span,
218	        });
