348	    // ─── `defaultProps` scanning ───────────────────────────────────────────────
349	
350	    /// Scan `Button.defaultProps = { size: 'md' }` and merge into the matching
351	    /// component mapping's `param_defaults` — the same field destructured
352	    /// defaults (`function Button({ size = 'md' })`) populate, via
353	    /// `extract_param_defaults`. Deprecated in React 19 but still shipped in
354	    /// real .d.ts/.tsx (MUI, among others).
355	    pub(super) fn try_scan_default_props<'a>(&mut self, stmt: &ExpressionStatement<'a>) {
356	        let Some((obj_name, "defaultProps", right)) = self.static_member_assignment(stmt) else { return };
357	        let Expression::ObjectExpression(defaults_obj) = right else { return };
358	
359	        let defaults: FxHashMap<std::string::String, RawDefault> = defaults_obj
360	            .properties
361	            .iter()
362	            .filter_map(|prop| match prop {
363	                ObjectPropertyKind::ObjectProperty(op) => {
364	                    let key = js_text::property_name(&op.key.static_name()?);
365	                    let raw_default = self.eval_expr_as_default(&op.value, DefaultSource::DefaultProps);
366	                    Some((key, raw_default))
367	                }
368	                _ => None,
369	            })
370	            .collect();
371	
372	        if defaults.is_empty() {
373	            return;
374	        }
375	
376	        if let Some(mapping) = self.data.component_mappings.iter_mut().find(|m| m.is_binding_named(&obj_name)) {
377	            mapping.param_defaults.extend(defaults);
378	        }
379	    }
380	
381	    // ─── `Object.assign(Parent, { Sub: ... })` inline-only sub-components ────
382	
383	    /// Detect `Object.assign(Parent, { Sub: function(...) {...}, ... })` and
384	    /// synthesize a component mapping for each inline function/arrow-function
385	    /// value whose key is PascalCase — the one sub-case of this pattern that
386	    /// isn't already covered: a sub-component that exists ONLY inside the
387	    /// object-literal argument, with no independent top-level binding of its
388	    /// own. A bare identifier reference (`{ Icon: IconImpl }`) is
389	    /// deliberately left alone: `IconImpl` is independently declared and
390	    /// already detected under its own name via Pattern 4/HOC, and
391	    /// `rdt-coverage.md`'s "compound components" investigation found no
392	    /// real-world case needing anything more than that — cosmetic
393	    /// dot-qualified naming (`"Parent.Sub"`) was considered and explicitly
394	    /// declined there as speculative.
395	    pub(super) fn try_scan_object_assign_sub_components<'a>(&mut self, stmt: &ExpressionStatement<'a>) {
396	        let Expression::CallExpression(call) = &stmt.expression else { return };
397	        self.scan_object_assign_call(call);
398	    }
399	
400	    /// The same scan for `const Root = Object.assign(RootImpl, { Item: (props: P) => … })`, whose call is a
401	    /// declaration's initializer and not a statement.
402	    pub(super) fn try_scan_object_assign_declarator<'a>(&mut self, init: Option<&Expression<'a>>) {
403	        if let Some(Expression::CallExpression(call)) = init.map(super::component::peel_expr) {
404	            self.scan_object_assign_call(call);
405	        }
406	    }
407	
408	    fn scan_object_assign_call<'a>(&mut self, call: &CallExpression<'a>) {
409	        let Expression::StaticMemberExpression(callee) = &call.callee else { return };
410	        if !matches!(&callee.object, Expression::Identifier(id) if id.name.as_str() == "Object") {
411	            return;
412	        }
413	        if callee.property.name.as_str() != "assign" {
414	            return;
415	        }
416	        let Some(Argument::Identifier(parent_id)) = call.arguments.first() else { return };
417	        if !is_pascal_case(parent_id.name.as_str()) {
418	            return;
419	        }
420	        let Some(second_arg) = call.arguments.get(1) else { return };
421	        let Some(Expression::ObjectExpression(obj)) = second_arg.as_expression() else { return };
422	
423	        for prop in &obj.properties {
424	            let ObjectPropertyKind::ObjectProperty(op) = prop else { continue };
425	            let Some(key_name) = op.key.static_name().map(|n| js_text::property_name(&n)) else { continue };
426	            if !is_pascal_case(&key_name) {
427	                continue;
428	            }
429	
430	            // Only inline function/arrow expressions carry a sub-component that
431	            // would otherwise be entirely unreachable; a bare identifier
432	            // reference is already independently detected under its own name.
433	            let (params, span_start, span_end) = match &op.value {
434	                Expression::FunctionExpression(fe) => (&fe.params, fe.span.start, fe.span.end),
435	                Expression::ArrowFunctionExpression(afe) => (&afe.params, afe.span.start, afe.span.end),
436	                Expression::Identifier(sub) => {
437	                    self.record_attached(Subject::local(sub.name.as_str()), parent_id.name.as_str(), &key_name);
438	                    continue;
439	                }
440	                _ => continue,
441	            };
442	            self.record_attached(Subject::Inline(span_start), parent_id.name.as_str(), &key_name);
443	            self.record_inline_sub_component(key_name, "an Object.assign-attached", params, span_start, span_end);
444	        }
445	    }
446	
447	    /// `Root.Item = (props: ItemProps) => …` at statement level: a sub-component that exists only on the assignment.
448	    /// An assigned identifier is already detected under its own name and attached by `record_member_assignment`.
449	    pub(super) fn try_scan_member_assigned_sub_component<'a>(&mut self, stmt: &ExpressionStatement<'a>) {
